package vaultor.linked;
import java.nio.file.*;import java.util.*;

public final class LinkedRetentionTests extends SafetyTests {
    public static void main(String[] args)throws Exception {
        check("150 acknowledged checkpoints coalesce only older drafts and retain latest rejected V plus validated L",()->{try(var f=new LinkedPublicationTests.LinkedFixture("guide.md","Base",null)){var doc=f.store.openLinked(OWNER,f.rootCap,"guide.md");for(int i=1;i<=150;i++)require(candidate(f.store,doc,i,"Draft "+i)!=null);f.store.journalDraft(OWNER,doc.document(),doc.epoch(),151,"Rejected current visual draft",null,null);var recovered=f.store.recover(OWNER);require(recovered.size()==1);require(recovered.getFirst().record().visual().equals("Rejected current visual draft"));require(Arrays.equals(recovered.getFirst().record().local(),LinkedStore.utf8("Draft 150")));require(Files.readString(f.file).equals("Base"));}});
        check("only acknowledged successful saves enter bounded twenty-version history",()->{try(var f=new LinkedPublicationTests.LinkedFixture("guide.md","Base",null)){for(int i=0;i<30;i++){var doc=f.store.openLinked(OWNER,f.rootCap,"guide.md");var saved=f.store.saveLinked(OWNER,doc.document(),doc.epoch(),candidate(f.store,doc,1,"Revision "+i),UUID.randomUUID().toString());require(saved.state().equals("COMMITTED"));f.store.acknowledgeLinkedSave(OWNER,saved.operation());f.store.closeDocument(OWNER,doc.document());}var recovered=f.store.recover(OWNER);require(recovered.size()==20);require(recovered.stream().allMatch(r->r.record()!=null&&r.record().state().equals("LINKED_ACKNOWLEDGED")));require(Files.readString(f.file).equals("Revision 29"));}});
        check("unacknowledged completed Save and uncertain conflict are never history-pruned",()->{final Path[] conflictPath={null};try(var f=new LinkedPublicationTests.LinkedFixture("guide.md","Base",(phase,op)->{if(phase.equals("replacement-before-publish")&&Journal.decode(Files.readAllBytes(op.resolve("00.rec"))).relative().equals("conflict.md"))require(external("create",conflictPath[0],"External occupant")==0);})){var doc=f.store.openLinked(OWNER,f.rootCap,"guide.md");var unacknowledged=f.store.saveLinked(OWNER,doc.document(),doc.epoch(),candidate(f.store,doc,1,"Unacknowledged saved source"),UUID.randomUUID().toString());require(unacknowledged.state().equals("COMMITTED"));conflictPath[0]=f.root.resolve("conflict.md");Files.writeString(conflictPath[0],"Conflict base");var conflict=f.store.openLinked(OWNER,f.rootCap,"conflict.md");var uncertain=f.store.saveLinked(OWNER,conflict.document(),conflict.epoch(),candidate(f.store,conflict,1,"Conflict local"),UUID.randomUUID().toString());require(uncertain.state().equals("RECOVERY_REQUIRED"));Files.writeString(f.root.resolve("other.md"),"Other");for(int i=0;i<25;i++){var other=f.store.openLinked(OWNER,f.rootCap,"other.md");var saved=f.store.saveLinked(OWNER,other.document(),other.epoch(),candidate(f.store,other,1,"Other "+i),UUID.randomUUID().toString());require(saved.state().equals("COMMITTED"));f.store.acknowledgeLinkedSave(OWNER,saved.operation());f.store.closeDocument(OWNER,other.document());}require(f.store.recover(OWNER).stream().anyMatch(r->r.operation().equals(unacknowledged.operation())&&r.record().state().startsWith("LINKED_COMMITTED:")));require(f.store.recover(OWNER).stream().anyMatch(r->r.operation().equals(uncertain.operation())&&r.record().state().startsWith("REPLACEMENT_UNCERTAIN:")));require(Files.readString(f.journal.resolve(unacknowledged.operation()).resolve("captured.md")).equals("Base"));require(Files.readString(conflictPath[0]).equals("External occupant"));}});
        Files.writeString(Path.of("native/linked-markdown/evidence/production/retention-tests.txt"),String.join("\n",results)+"\npassed="+passed+" failed="+failed+"\n");System.out.println("TOTAL "+passed+" passed; "+failed+" failed");if(failed>0)System.exit(1);
    }
}
